GruppoA() = { 10, 12, 11, 10, 13, 11, 12 }
GruppoB() = { 5, 20, 8, 25, 2, 18, 6 }
PRINT "Gruppo A - Media: "; STATS.MEAN(GruppoA()); " Varianza: "; FORMAT(STATS.VARIANCE(GruppoA()), "#.00")
PRINT "Gruppo B - Media: "; STATS.MEAN(GruppoB()); " Varianza: "; FORMAT(STATS.VARIANCE(GruppoB()), "#.00")

AzioniA() = { 100, 102, 105, 103, 108, 110 }
AzioniB() = { 50, 51, 48, 52, 49, 53 }
AzioniC() = { 100, 98, 96, 94, 92, 90 }
CorrAB = STATS.CORRELATION(AzioniA(), AzioniB())
CorrAC = STATS.CORRELATION(AzioniA(), AzioniC())
PRINT "Corr(A,B): "; FORMAT(CorrAB, "#.00"); " (scorrelate)"
PRINT "Corr(A,C): "; FORMAT(CorrAC, "#.00"); " (correlazione negativa)"
